:root {
  --header-height: clamp(4rem, 1vw + 3.5rem, 5rem);
  --site-shell-gap: clamp(1rem, 2vw, 1.8rem);
  --footer-reveal: clamp(11rem, 20vw, 15rem);
}

/* Site Wrapper
/* ---------------------------------------------------------- */

.site-wrapper {
  background: var(--color-bg);
  min-height: 100vh;
  color: var(--color-base);
  position: relative;
}

.site-content-shell {
  position: relative;
  z-index: 2;
  background: var(--color-bg);
  box-shadow: 0 40px 90px rgba(10, 10, 10, 0.18), 0 20px 35px rgba(10, 10, 10, 0.08),
    0 8px 14px rgba(10, 10, 10, 0.06);
}

[data-theme='dark'] .site-wrapper {
  background: radial-gradient(circle at top, rgba(201, 166, 160, 0.05), transparent 50%),
    var(--color-bg);
}

/* Header
/* ---------------------------------------------------------- */

.site-head {
  position: sticky;
  top: 0;
  width: 100%;
  background: rgba(250, 247, 242, 0.95);
  backdrop-filter: blur(8px);
  box-shadow: none;
  border-bottom: 1px solid var(--color-border);
  z-index: 20;
}

[data-theme='dark'] .site-head {
  background: rgba(23, 21, 20, 0.95);
  box-shadow: none;
  border-bottom-color: var(--color-border);
}

.site-head-container {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 var(--site-shell-gap);
  height: var(--header-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.site-head-logo img {
  max-height: calc(var(--header-height) - 1rem);
}

.site-head-left,
.site-head-right {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.site-head-left a,
.site-head-right a {
  font-family: var(--font-sans-serif);
  font-size: 1.1rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  font-weight: 300;
  color: var(--color-base);
  opacity: 0.6;
  text-decoration: none;
  transition: opacity 0.3s ease, color 0.3s ease;
}

.site-head-left a:hover,
.site-head-right a:hover {
  opacity: 1;
  color: var(--color-accent);
  text-decoration: none;
}

/* Footer
/* ---------------------------------------------------------- */

.site-foot {
  margin-top: var(--site-shell-gap);
  padding: 3rem var(--site-shell-gap) 4rem;
  border-top: 1px solid var(--color-border);
}

[data-theme='dark'] .site-foot {
  border-top-color: var(--color-border);
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1;
  min-height: var(--footer-reveal);
  padding: 2.4rem var(--site-shell-gap) 3.1rem;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.7), #f3f0e8 30%, #ece6db);
  overflow: hidden;
}

.site-foot-logo {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0.18;
}

.site-foot-logo svg {
  width: min(94vw, 820px);
  height: auto;
}

.site-foot-logo svg .st0 {
  fill: none;
  stroke: rgba(40, 37, 32, 0.5);
  stroke-width: 1.5;
  stroke-dasharray: 2800;
  stroke-dashoffset: 2800;
  animation: footer-logo-write 5.8s cubic-bezier(0.67, 0.01, 0.38, 0.98) forwards;
}

.site-foot-logo svg path:nth-of-type(2) {
  animation-delay: 0.3s;
}

.site-foot-logo svg path:nth-of-type(3) {
  animation-delay: 0.6s;
}

.site-foot-logo svg path:nth-of-type(4) {
  animation-delay: 0.9s;
}

.site-foot-logo svg path:nth-of-type(5) {
  animation-delay: 1.2s;
}

.site-foot-inner {
  max-width: 1320px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.8rem;
  position: relative;
  z-index: 2;
}

.site-foot-brand strong {
  font-family: var(--font-display);
  font-weight: 300;
  letter-spacing: 0.06em;
  font-size: 1.2rem;
}

.site-foot-bio {
  flex: 1 1 auto;
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 4rem);
  font-family: var(--font-sans-serif);
  font-size: 0.7rem;
  line-height: 1.4;
  letter-spacing: 0.035em;
  text-align: center;
  white-space: nowrap;
  color: var(--color-base);
  opacity: 0.48;
}

.site-foot-nav {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.site-foot-nav a {
  font-family: var(--font-sans-serif);
  letter-spacing: 0.12em;
  text-transform: uppercase;
