---
title: Gallery Orientation Policy
read_when:
  - "Adding or editing lookbook posts"
  - "Fixing gallery layout imbalance"
tags:
  - gallery
  - qa
---

Gallery posts on Lovely Sunday pair photos only when they share the same orientation. When two slides appear side by side in a 50/50 row, both images must either be landscape or portrait; mixed pairs get promoted to full-width so the layout stays balanced.

To enforce the rule, the build now runs `npm run check:gallery-orientations`. The script under `scripts/check-gallery-orientations.mjs` mirrors the browser pairing logic and fails the build if it finds adjacent half-spans with different `data-image-dimensions`.

When working with legacy Squarespace content, keep the `data-image-dimensions` attributes intact so the orientation helper can work, and rely on the inline script in `LegacyHtmlPage.astro` to mark up balanced pairs automatically.

-- implementation --
---
import Layout from "../layouts/Layout.astro";
import "../styles/components/legacy-page.css";
import type { LegacyPage } from "../lib/legacy-pages";

export interface Props {
  page: LegacyPage;
}

const { page } = Astro.props;
const { view } = page;

const pageType = view.kind === "gallery" ? "article" : "collection";
const allParagraphs = view.description
  ? [view.description, ...view.paragraphs]
  : view.paragraphs;
const hasVisuals = Boolean(view.heroImage) || view.images.length > 0;
const socialImage = view.heroImage?.src || view.images[0]?.src;
---

<Layout
  title={view.title}
  description={view.description}
  seo={{ image: socialImage, pageType }}
>
  <article class={`legacy-page legacy-page--${view.kind}`}>
    <header class={`legacy-page-hero${view.heroImage ? " has-media" : ""}`}>
      <div class="legacy-page-copy">
        <p class="legacy-page-eyebrow">{view.eyebrow}</p>
        <h1>{view.title}</h1>

        {allParagraphs.slice(0, view.heroImage ? 2 : 3).map((paragraph) => (
          <p>{paragraph}</p>
        ))}
      </div>

      {view.heroImage && (
        <figure class="legacy-page-hero-media">
          <img
            src={view.heroImage.src}
            alt={view.heroImage.alt}
            width={view.heroImage.width}
            height={view.heroImage.height}
            loading="eager"
            decoding="sync"
            fetchpriority="high"
          />
        </figure>
      )}
    </header>

    {view.links.length > 0 && (
      <section class="legacy-page-links" aria-label="Explore more">
        <ul>
          {view.links.map((link) => (
            <li>
              <a href={link.href} rel={link.external ? "noreferrer" : undefined}>
                {link.label}
              </a>
            </li>
          ))}
        </ul>
      </section>
    )}

    {view.images.length > 0 && (
      <section class={`legacy-page-gallery${hasVisuals ? "" : " no-hero"}`} aria-label="Gallery">
        {view.images.map((image, index) => (
          <figure class="legacy-page-frame">
            <img
              src={image.src}
              alt={image.alt}
              width={image.width}
              height={image.height}
              loading={index < 4 ? "eager" : "lazy"}
              decoding="async"
              fetchpriority={index === 0 && !view.heroImage ? "high" : undefined}
            />
          </figure>
        ))}
      </section>
    )}

    {allParagraphs.slice(view.heroImage ? 2 : 3).length > 0 && (
      <section class="legacy-page-body">
        {allParagraphs.slice(view.heroImage ? 2 : 3).map((paragraph) => (
          <p>{paragraph}</p>
        ))}
      </section>
    )}
  </article>

  <slot />
</Layout>
