// @ts-check
import { defineConfig } from "astro/config";
import react from "@astrojs/react";
import sitemap from "@astrojs/sitemap";
import robotsTxt from "astro-robots-txt";

const site = process.env.SITE_URL ?? "https://www.lovelysunday.co";
const isStorybook = process.env.STORYBOOK === "true";
const pageMarkdown = isStorybook
    ? null
    : (await import("@nuasite/llm-enhancements")).default;
const aiCrawlerUserAgents = [
    "GPTBot",
    "ChatGPT-User",
    "OAI-SearchBot",
    "OAI-ImageBot",
    "ClaudeBot",
    "Claude-Web",
    "PerplexityBot",
    "Perplexity-User",
    "Google-Extended",
    "Applebot-Extended",
    "CCBot",
    "Bytespider",
    "Amazonbot",
];
const llmSections = [
    "## Primary Sections",
    "- Home: featured editorials and archive highlights.",
    "- Lookbook: image-first outfit collections and tagged style edits.",
    "- Daily Diary: chronological notes, travel moments, and editorial updates.",
    "- About: background on Lovely Sunday, Aileen, and Rory.",
    "- Contact: collaboration and partnership details.",
    "",
    "## Access Notes",
    "- Prefer canonical URLs when citing.",
    "- Markdown endpoints are available by appending `.md` to page URLs.",
    "- A full-text overview lives at `/llms-full.txt`.",
].join("\n");
const llmInstructions =
    "Cite canonical URLs, prefer markdown endpoints when available, and use page titles plus descriptions as the primary summary source.";

export default defineConfig({
    site,
    output: "static",
    trailingSlash: "ignore",
    server: {
        host: "localhost",
        port: 4321,
    },
    vite: {
        server: {
            allowedHosts: ["lovelysunday.test"],
            watch: {
                ignored: ["**/dist/**", "**/storybook-static/**"],
            },
        },
    },
    build: {
        format: "directory",
    },
    integrations: isStorybook ? [] : [
        react(),
        sitemap(),
        pageMarkdown({
            contentDir: "src/content",
            includeStaticPages: true,
            includeFrontmatter: true,
            llmEndpoint: {
                siteName: "Lovely Sunday",
                description:
                    "Fashion-led visual stories, lookbooks, and travel diaries from Aileen and Rory.",
                additionalContent: llmSections,
            },
            llmsTxt: {
                siteName: "Lovely Sunday",
                description:
                    "Fashion-led visual stories, lookbooks, and travel diaries from Aileen and Rory.",
                allowCrawling: true,
                instructions: llmInstructions,
                additionalContent: llmSections,
            },
        }),
        robotsTxt({
            host: true,
            sitemap: true,
            policy: [
                { userAgent: "*", allow: "/" },
                ...aiCrawlerUserAgents.map((userAgent) => ({
                    userAgent,
                    allow: "/",
                })),
            ],
        }),
    ],
});
interface RouteMetaInput {
  title?: string | null;
  canonical?: string | null;
  meta?: {
    description?: string | null;
    robots?: string | null;
  } | null;
  openGraph?: {
    title?: string | null;
    description?: string | null;
    image?: string | null;
    type?: string | null;
    url?: string | null;
  } | null;
  twitter?: {
    card?: "summary" | "summary_large_image" | "app" | "player" | null;
    title?: string | null;
    description?: string | null;
    image?: string | null;
  } | null;
  jsonLd?: string[] | null;
}

export interface RouteSeoMeta {
  title?: string;
  canonical?: string;
  description?: string;
  robots?: string;
  openGraph: {
    title?: string;
    description?: string;
    image?: string;
    type?: string;
    url?: string;
  };
  twitter: {
    card?: "summary" | "summary_large_image" | "app" | "player";
    title?: string;
    description?: string;
    image?: string;
  };
  jsonLd: string[];
}

const pageJsonModules = import.meta.glob<RouteMetaInput>("../../capture/page_json/*.json", {
  eager: true,
  import: "default",
});
const siteOrigin = new URL(import.meta.env.SITE ?? "https://lovelysunday.co").origin;

const normalizePathname = (pathname: string): string => {
  const [pathOnly] = pathname.split("?");
  const collapsed = pathOnly.replace(/\/{2,}/g, "/");
  if (!collapsed || collapsed === "/") return "/";
  return collapsed.replace(/\/$/, "");
};

const normalizeLegacyUrl = (value?: string | null): string | undefined => {
  if (!value) return undefined;

  try {
    const url = new URL(value);
    if (url.hostname === "lovelysunday.co" || url.hostname === "www.lovelysunday.co") {
      const productionUrl = new URL(siteOrigin);
      url.protocol = productionUrl.protocol;
      url.host = productionUrl.host;
    }
    return url.toString();
  } catch {
    return value ?? undefined;
  }
};

const canonicalToPath = (canonical?: string | null): string | null => {
  if (!canonical) return null;
  try {
    return normalizePathname(new URL(canonical).pathname || "/");
  } catch {
    return null;
  }
};

/**
 * Prevent JSON-LD strings from closing a <script> tag early.
 * The HTML parser sees </script> regardless of the script's type attribute,
 * so we replace it with a safe escaped form that is valid JSON but won't
 * trigger the HTML parser.
 */
const sanitizeJsonLd = (raw: string): string =>
  raw.replace(/<\/(script)/gi, "<\\/$1");

const routeSeoByPath = new Map<string, RouteSeoMeta>();

for (const data of Object.values(pageJsonModules)) {
  const path = canonicalToPath(data.canonical) || canonicalToPath(data.openGraph?.url);
  if (!path) continue;

  const existing = routeSeoByPath.get(path);
  if (existing && existing.canonical && data.canonical) {
    continue;
  }

  routeSeoByPath.set(path, {
    title: data.title ?? undefined,
    canonical: normalizeLegacyUrl(data.canonical),
    description: data.meta?.description ?? undefined,
    robots: data.meta?.robots ?? undefined,
    openGraph: {
      title: data.openGraph?.title ?? undefined,
      description: data.openGraph?.description ?? undefined,
      image: data.openGraph?.image ?? undefined,
      type: data.openGraph?.type ?? undefined,
      url: normalizeLegacyUrl(data.openGraph?.url),
    },
    twitter: {
      card: data.twitter?.card ?? undefined,
      title: data.twitter?.title ?? undefined,
      description: data.twitter?.description ?? undefined,
      image: data.twitter?.image ?? undefined,
    },
    jsonLd: (data.jsonLd ?? [])
      .filter((entry) => !/"@context"\s*:\s*"http:\/\/schema\.org"/.test(entry))
      .map(sanitizeJsonLd),
  });
}

if (!routeSeoByPath.has("/") && routeSeoByPath.has("/index")) {
  const indexMeta = routeSeoByPath.get("/index");
  if (indexMeta) {
    routeSeoByPath.set("/", indexMeta);
  }
}

export const getRouteSeoMeta = (pathname: string): RouteSeoMeta | undefined =>
  routeSeoByPath.get(normalizePathname(pathname));
#!/usr/bin/env node
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative, resolve } from "node:path";
import { load } from "cheerio";

const repoRoot = resolve(import.meta.dirname, "..");
const distDir = resolve(repoRoot, "dist");
const productionOrigin = new URL(process.env.SITE_URL ?? "https://lovelysunday.co").origin;
const issues = [];

function walk(directory) {
  return readdirSync(directory).flatMap((entry) => {
    const path = join(directory, entry);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });
}

function requireFile(relativePath) {
  const path = resolve(distDir, relativePath);
  if (!existsSync(path)) {
    issues.push(`Missing generated artifact: dist/${relativePath}`);
    return "";
  }
  return readFileSync(path, "utf8");
}

const doubleSlashRoute = "lookbook-double/looks/babes-day/index.html";
const doubleSlashHtml = requireFile(doubleSlashRoute);
if (doubleSlashHtml) {
  const $ = load(doubleSlashHtml);
  if ($("main").length !== 1) issues.push(`${doubleSlashRoute}: expected one main landmark`);
  if ($("h1").length !== 1) issues.push(`${doubleSlashRoute}: expected one H1`);
  if (!$("h1").text().trim()) issues.push(`${doubleSlashRoute}: H1 must have text`);
}

const builtFiles = walk(distDir);
for (const file of builtFiles.filter(
  (path) => path.endsWith(".html") && relative(distDir, path) !== "admin/index.html",
)) {
  const html = readFileSync(file, "utf8");
  const $ = load(html);
  const label = relative(repoRoot, file);

  if ($("title").length !== 1) issues.push(`${label}: expected exactly one title`);
  if ($('link[rel="canonical"]').length !== 1) issues.push(`${label}: expected exactly one canonical`);
  if ($('meta[name="description"]').length !== 1) issues.push(`${label}: expected one description`);
  if ($('meta[property="og:title"]').length !== 1) issues.push(`${label}: expected one og:title`);
  if ($('meta[name="twitter:card"]').length !== 1) issues.push(`${label}: expected one twitter:card`);

  const canonical = $('link[rel="canonical"]').attr("href");
  if (canonical && new URL(canonical).origin !== productionOrigin) {
    issues.push(
      `${label}: canonical is not on the production origin ${productionOrigin} (${canonical})`,
    );
  }

  for (const script of $('script[type="application/ld+json"]').toArray()) {
    try {
      JSON.parse($(script).text());
    } catch (error) {
      issues.push(`${label}: invalid JSON-LD (${error.message})`);
    }
  }

  if (html.includes("AgentationToolbar") || html.includes("agentation")) {
    issues.push(`${label}: Agentation leaked into a production build`);
  }
}

const adminHtml = requireFile("admin/index.html");
if (adminHtml) {
  const $ = load(adminHtml);
  const cmsScript = $("script[src]").attr("src");
  if (cmsScript !== "https://unpkg.com/@sveltia/cms@0.164.2/dist/sveltia-cms.js") {
    issues.push(`admin/index.html: expected pinned Sveltia CMS script`);
  }
  if ($('meta[name="robots"]').attr("content") !== "noindex, nofollow") {
    issues.push(`admin/index.html: expected noindex, nofollow`);
  }
}

const cmsConfig = requireFile("admin/config.yml");
for (const expected of [
  "name: github",
  "repo: manikrathee/lovely-sunday",
  "branch: master",
]) {
  if (cmsConfig && !cmsConfig.includes(expected)) {
    issues.push(`admin/config.yml missing ${expected}`);
  }
}

const robots = requireFile("robots.txt");
for (const expected of ["User-agent: GPTBot", "User-agent: ClaudeBot", "Sitemap:"]) {
  if (robots && !robots.includes(expected)) issues.push(`robots.txt missing ${expected}`);
}

for (const artifact of [
  "llms.txt",
  "llms-full.txt",
  ".well-known/llm.md",
  "sitemap-index.xml",
  "index.md",
]) {
  requireFile(artifact);
}

if (issues.length > 0) {
  console.error(`✖ Built-site validation failed with ${issues.length} issue(s):`);
  for (const issue of issues) console.error(`  - ${issue}`);
  process.exit(1);
}

console.log("✓ Built-site validation passed: routes, SEO, AI discovery, and dev-only tooling.");
